-- Correct parser-derived casting times and concentration metadata.
update public.spell_catalog set casting_time = '1 минута' where slug = 'mending';
update public.spell_catalog set casting_time = '1 час' where slug = 'find-familiar';
update public.spell_catalog set casting_time = '1 минута' where slug in ('identify','illusory-script','augury','magic-mouth','magic-circle','phantom-steed','tiny-hut','animate-dead');
update public.spell_catalog set casting_time = '10 минут' where slug in ('prayer-of-healing','clairvoyance','fabricate','hallucinatory-terrain','private-sanctum');
update public.spell_catalog set casting_time = '1 час', concentration = false where slug = 'glyph-of-warding';
update public.spell_catalog set casting_time = 'Действие (Зарастание) или 8 часов (Обогащение)' where slug = 'plant-growth';

-- Restore operational details lost in concise Russian summaries.
update public.spell_catalog
set effect_summary = 'Скорость цели удваивается, КД повышается на 2, спасброски Ловкости совершаются с преимуществом. Каждый ход цель получает дополнительное действие, которое можно потратить только на одну атаку, Рывок, Отход, Спрятаться или Использование.'
where slug = 'haste';

update public.spell_catalog
set effect_summary = 'При провале цель не может использовать Бонусные действия и Реакции и в начале каждого хода бросает 1к10: 1 — не совершает действие и тратит всё движение, двигаясь в направлении по 1к4 (1 — север, 2 — восток, 3 — юг, 4 — запад); 2–6 — не двигается и не действует; 7–8 — не двигается и совершает одну рукопашную атаку по случайному существу в пределах досягаемости, а если цели нет — не действует; 9–10 — сама выбирает поведение.'
where slug = 'confusion';

update public.spell_catalog
set notes = 'Ритуал. Бонусным действием раз за ход можно приказать слуге переместиться на 15 футов и взаимодействовать с предметом. Если слуга падает до 0 HP, заклинание заканчивается. Если задание уведёт его дальше 60 футов от тебя, заклинание заканчивается.'
where slug = 'unseen-servant';

update public.spell_catalog
set effect_summary = 'Магически запирает закрываемый объект. Немагическими средствами открыть его нельзя. При наложении можно назначить существ, которые открывают его свободно, и пароль: если произнести его в пределах 5 футов от объекта, замок отключается на 1 минуту.'
where slug = 'arcane-lock';

update public.spell_catalog
set notes = 'Сфера перепрыгивает ямы до 10 футов и препятствия до 5 футов. Поджигает незакреплённые горючие предметы, которых касается. Даёт яркий свет в радиусе 20 футов и тусклый ещё на 20 футов.'
where slug = 'flaming-sphere';

update public.spell_catalog
set notes = 'Чтобы найти конкретный предмет, нужно хотя бы раз видеть его вблизи — в пределах 30 футов. Любая толщина свинца на прямом пути блокирует поиск.'
where slug = 'locate-object';

update public.spell_catalog
set effect_summary = 'Создаёшь в разуме цели иллюзию предмета, существа или явления размером до куба 10 футов, которую воспринимает только она; иллюзия включает звук, температуру и другие ощущения. При провале спасброска цель считает её реальной и сама объясняет несостыковки. Опасная иллюзия может раз за каждый твой ход нанести 2к8 психического урона, если цель находится в области иллюзии или в пределах 5 футов от неё.',
    notes = 'Цель может действием Изучения сделать Интеллект (Расследование) против Сл спасброска заклинаний; при успехе понимает, что это иллюзия, и заклинание заканчивается.'
where slug = 'phantasmal-force';

update public.spell_catalog
set effect_summary = 'Касаешься верёвки: один её конец поднимается вверх, и наверху открывается невидимый портал 3 × 5 футов во внепространственное помещение. Внутри помещается до восьми существ Среднего размера или меньше. Верёвку можно втянуть внутрь помещения или снова спустить наружу. Через портал нельзя проводить атаки, заклинания и другие эффекты внутрь или наружу.',
    notes = 'Существа внутри видят наружу через портал. Всё находящееся внутри выпадает наружу, когда заклинание заканчивается.'
where slug = 'rope-trick';

update public.spell_catalog
set notes = 'Подъём воды повышает уровень стоячей воды до 20 футов; в большом водоёме создаёт волну высотой 20 футов, которая переносит Огромные и меньшие суда и даёт им 25% шанс опрокинуться; пока этот режим действует, волна повторяется в начале твоего следующего хода. Разделение воды создаёт траншею и стены воды; после смены режима или окончания заклинания вода заполняет траншею в течение следующего раунда. Изменение течения заставляет воду течь в выбранном направлении, даже вверх по стенам, пока она в области. Водоворот требует воду минимум 50 × 50 футов и 25 футов глубиной; сам водоворот имеет 5 футов у основания, до 50 футов наверху и высоту 25 футов. Существа в воде в пределах 25 футов подтягиваются на 10 футов; при первом входе за ход или окончании хода внутри делают спасбросок Силы, получая 2к8 дробящего при провале или половину при успехе. Чтобы отплыть, нужно сначала действием сделать Силу (Атлетика) против Сл спасброска заклинаний.'
where slug = 'control-water';

update public.spell_catalog
set effect_summary = 'Выбираешь одно из трёх изменений: жабры и скорость плавания, равную Скорости; изменение внешности и голоса без смены размера и базовой формы; либо когти, клыки, рога или копыта, наносящие 1к6 подходящего урона. Для атак и урона этим природным оружием используешь модификатор характеристики заклинаний вместо Силы. Действием Магии можно менять выбранный вариант.'
where slug = 'alter-self';

update public.spell_catalog
set notes = 'Все выбранные цели должны оставаться в пределах 30 футов в течение всех 10 минут сотворения. Одно и то же существо не может получить эффект снова, пока не завершит долгий отдых.'
where slug = 'prayer-of-healing';
